from pathlib import Path


def replace_once(text: str, old: str, new: str, label: str) -> str:
    count = text.count(old)
    if count != 1:
        raise SystemExit(f'{label}: expected exactly one match, found {count}')
    return text.replace(old, new, 1)

path = Path('core/parsers/byte-source.ts')
text = path.read_text()
old = """export interface RandomAccessByteSource {\n  readonly size: number;\n  read(offset: number, length: number): Promise<Uint8Array>;\n  performanceSnapshot?(): ByteSourcePerformanceSnapshot;\n}\n"""
new = """export interface RandomAccessByteSource {\n  readonly size: number;\n  /**\n   * Optional byte boundary that is cheap for the source to read within.\n   * Callers may use this to avoid requesting spans that force the source to\n   * join/copy multiple backing pages. This is a performance hint only.\n   */\n  readonly preferredReadAlignmentBytes?: number;\n  read(offset: number, length: number): Promise<Uint8Array>;\n  performanceSnapshot?(): ByteSourcePerformanceSnapshot;\n}\n"""
text = replace_once(text, old, new, 'byte-source hint')
path.write_text(text)

path = Path('apps/web/src/adapters/blob-byte-source.ts')
text = path.read_text()
old = """export class BlobByteSource implements RandomAccessByteSource {\n  readonly size: number;\n  private readonly blob: Blob;\n"""
new = """export class BlobByteSource implements RandomAccessByteSource {\n  readonly size: number;\n  readonly preferredReadAlignmentBytes: number | undefined;\n  private readonly blob: Blob;\n"""
text = replace_once(text, old, new, 'blob alignment property')
old = """  public constructor(blob: Blob) {\n    this.blob = blob;\n    this.size = blob.size;\n  }\n"""
new = """  public constructor(blob: Blob) {\n    this.blob = blob;\n    this.size = blob.size;\n    this.preferredReadAlignmentBytes = this.size > CACHE_LIMIT_BYTES\n      ? CACHE_PAGE_SIZE\n      : undefined;\n  }\n"""
text = replace_once(text, old, new, 'blob alignment constructor')
path.write_text(text)

path = Path('core/parsers/mlg/mlg-channel-data.ts')
text = path.read_text()
old = """        let batchLastIndex = batchFirstIndex;\n        let batchEndByte = firstRecordOffset + BLOCK_HEADER_LENGTH + maxFieldEnd;\n        while (batchLastIndex + 1 < endSampleIndex) {\n          const nextIndex = batchLastIndex + 1;\n          const nextRecordOffset = this.recordIndex.offsets[nextIndex];\n          if (nextRecordOffset === undefined) break;\n          const nextEndByte = nextRecordOffset + BLOCK_HEADER_LENGTH + maxFieldEnd;\n          if (nextEndByte - batchStartByte > MAX_BATCH_SPAN) break;\n          batchLastIndex = nextIndex;\n          batchEndByte = nextEndByte;\n        }\n"""
new = """        let batchLastIndex = batchFirstIndex;\n        let batchEndByte = firstRecordOffset + BLOCK_HEADER_LENGTH + maxFieldEnd;\n        const readAlignmentBytes = this.source.preferredReadAlignmentBytes;\n        const alignedBoundaryEnd = readAlignmentBytes && readAlignmentBytes > 0\n          ? (Math.floor(batchStartByte / readAlignmentBytes) + 1) * readAlignmentBytes\n          : undefined;\n        while (batchLastIndex + 1 < endSampleIndex) {\n          const nextIndex = batchLastIndex + 1;\n          const nextRecordOffset = this.recordIndex.offsets[nextIndex];\n          if (nextRecordOffset === undefined) break;\n          const nextEndByte = nextRecordOffset + BLOCK_HEADER_LENGTH + maxFieldEnd;\n          if (nextEndByte - batchStartByte > MAX_BATCH_SPAN) break;\n          // A paged source can return a subarray without copying when a read\n          // stays within one backing page. Stop before the next page boundary\n          // instead of forcing BlobByteSource to allocate/join an ~8 MiB span.\n          // If the first record itself crosses a boundary, keep that unavoidable\n          // small cross-page read but do not add more records to it.\n          if (alignedBoundaryEnd !== undefined && nextEndByte > alignedBoundaryEnd) break;\n          batchLastIndex = nextIndex;\n          batchEndByte = nextEndByte;\n        }\n"""
text = replace_once(text, old, new, 'aligned batch planning')
path.write_text(text)

Path('tests/parsers/mlg/mlg-channel-read-alignment.test.ts').write_text("""import { describe, expect, it } from 'vitest';\nimport type { RandomAccessByteSource } from '../../../core/parsers/byte-source';\nimport { MlgNumericChannelDataSource } from '../../../core/parsers/mlg/mlg-channel-data';\nimport type { MlgFieldDescriptor } from '../../../core/parsers/mlg/mlg-format';\nimport type { MlgRecordIndex } from '../../../core/parsers/mlg/mlg-records';\n\nclass TrackingSource implements RandomAccessByteSource {\n  readonly size: number;\n  readonly preferredReadAlignmentBytes = 16;\n  readonly reads: Array<{ offset: number; length: number }> = [];\n  private readonly bytes: Uint8Array;\n\n  constructor(size: number) {\n    this.size = size;\n    this.bytes = new Uint8Array(size);\n  }\n\n  setUint16(offset: number, value: number): void {\n    new DataView(this.bytes.buffer).setUint16(offset, value, false);\n  }\n\n  setUint32(offset: number, value: number): void {\n    new DataView(this.bytes.buffer).setUint32(offset, value, false);\n  }\n\n  async read(offset: number, length: number): Promise<Uint8Array> {\n    this.reads.push({ offset, length });\n    return this.bytes.subarray(offset, offset + length);\n  }\n}\n\nfunction scalarField(widthBytes = 2): MlgFieldDescriptor {\n  return {\n    index: 0,\n    offset: 0,\n    kind: 'scalar',\n    type: widthBytes === 4 ? 4 : 2,\n    name: 'RPM',\n    units: 'rpm',\n    displayStyle: 0,\n    widthBytes,\n    category: '',\n    scale: 1,\n    transform: 0,\n    digits: 0,\n  };\n}\n\nfunction recordIndex(offsets: readonly number[]): MlgRecordIndex {\n  return {\n    offsets: Float64Array.from(offsets),\n    timeMs: Float64Array.from(offsets.map((_value, index) => index * 10)),\n    counters: Uint8Array.from(offsets.map((_value, index) => index)),\n    crcValid: Uint8Array.from(offsets.map(() => 1)),\n  };\n}\n\ndescribe('MLG channel source read alignment', () => {\n  it('keeps decoder batches inside the source preferred page boundary', async () => {\n    const source = new TrackingSource(64);\n    const offsets = [0, 12, 24, 36];\n    offsets.forEach((offset, index) => source.setUint16(offset + 4, 100 + index));\n    const data = new MlgNumericChannelDataSource(source, [scalarField()], recordIndex(offsets));\n\n    const result = await data.readChannelsRange(['mlg:0'], 0, offsets.length);\n\n    expect([...result.ranges.get('mlg:0')!.values]).toEqual([100, 101, 102, 103]);\n    expect(source.reads).toEqual([\n      { offset: 4, length: 2 },\n      { offset: 16, length: 14 },\n      { offset: 40, length: 2 },\n    ]);\n    expect(source.reads.every(({ offset, length }) =>\n      Math.floor(offset / 16) === Math.floor((offset + length - 1) / 16),\n    )).toBe(true);\n  });\n\n  it('allows an unavoidable cross-page read when one selected field spans a boundary', async () => {\n    const source = new TrackingSource(48);\n    const offsets = [10, 26];\n    source.setUint32(14, 101);\n    source.setUint32(30, 102);\n    const data = new MlgNumericChannelDataSource(source, [scalarField(4)], recordIndex(offsets));\n\n    const result = await data.readChannelsRange(['mlg:0'], 0, offsets.length);\n\n    expect([...result.ranges.get('mlg:0')!.values]).toEqual([101, 102]);\n    expect(source.reads).toEqual([\n      { offset: 14, length: 4 },\n      { offset: 30, length: 4 },\n    ]);\n  });\n});\n""")
